CREATE TABLE IF NOT EXISTS "users" (
	-- Surrogate primary key. Global: one account across every server.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Global handle, unique across the platform and compared case-insensitively.
	"username" VARCHAR(32) NOT NULL UNIQUE,
	-- Global display name. Null falls back to the username, and a per-server nickname overrides both.
	"display_name" VARCHAR(32),
	-- Login address. Null for a bot account, which authenticates with a token instead.
	"email" VARCHAR(320) UNIQUE,
	-- CDN URL of the global avatar.
	"avatar_url" VARCHAR(500),
	-- Bots are users with the same permission machinery, which is why there is no separate bots table.
	"is_bot" BOOLEAN NOT NULL DEFAULT false,
	-- Required before a user can hold an administrator role on a server that enforces it.
	"mfa_enabled" BOOLEAN NOT NULL DEFAULT false,
	-- Account creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "users" IS 'A global account. Nothing server-specific lives here - that is the entire point of the guild_members table.';
COMMENT ON COLUMN "users"."id" IS 'Surrogate primary key. Global: one account across every server.';
COMMENT ON COLUMN "users"."username" IS 'Global handle, unique across the platform and compared case-insensitively.';
COMMENT ON COLUMN "users"."display_name" IS 'Global display name. Null falls back to the username, and a per-server nickname overrides both.';
COMMENT ON COLUMN "users"."email" IS 'Login address. Null for a bot account, which authenticates with a token instead.';
COMMENT ON COLUMN "users"."avatar_url" IS 'CDN URL of the global avatar.';
COMMENT ON COLUMN "users"."is_bot" IS 'Bots are users with the same permission machinery, which is why there is no separate bots table.';
COMMENT ON COLUMN "users"."mfa_enabled" IS 'Required before a user can hold an administrator role on a server that enforces it.';
COMMENT ON COLUMN "users"."created_at" IS 'Account creation time.';

CREATE TABLE IF NOT EXISTS "guilds" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Server name shown in the sidebar. Not unique: server names collide freely.
	"name" VARCHAR(100) NOT NULL,
	-- The one account that bypasses every permission check, including explicit denies.
	"owner_id" BIGINT NOT NULL,
	-- CDN URL of the server icon.
	"icon_url" VARCHAR(500),
	-- Channel that receives join and boost notices. Null when the owner turned them off.
	"system_channel_id" BIGINT,
	-- Permission bitfield of the implicit @everyone role, stored here so a server always has a baseline even before any role is created.
	"default_permissions" BIGINT NOT NULL DEFAULT 0,
	-- 0 none through 4 phone-verified. Gates who may send messages at all.
	"verification_level" SMALLINT NOT NULL DEFAULT 0,
	-- Server creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "guilds" IS 'A server. It is the permission boundary: roles, channels, nicknames and bans all exist only inside one guild.';
COMMENT ON COLUMN "guilds"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "guilds"."name" IS 'Server name shown in the sidebar. Not unique: server names collide freely.';
COMMENT ON COLUMN "guilds"."owner_id" IS 'The one account that bypasses every permission check, including explicit denies.';
COMMENT ON COLUMN "guilds"."icon_url" IS 'CDN URL of the server icon.';
COMMENT ON COLUMN "guilds"."system_channel_id" IS 'Channel that receives join and boost notices. Null when the owner turned them off.';
COMMENT ON COLUMN "guilds"."default_permissions" IS 'Permission bitfield of the implicit @everyone role, stored here so a server always has a baseline even before any role is created.';
COMMENT ON COLUMN "guilds"."verification_level" IS '0 none through 4 phone-verified. Gates who may send messages at all.';
COMMENT ON COLUMN "guilds"."created_at" IS 'Server creation time.';

CREATE INDEX "idx_guilds_owner"
ON "guilds" ("owner_id");

CREATE TABLE IF NOT EXISTS "channels" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning server.
	"guild_id" BIGINT NOT NULL,
	-- Containing category. Null for a top-level channel; a self-reference is how one table holds both categories and the channels inside them.
	"parent_id" BIGINT,
	-- text | voice | category | announcement | forum. A category is a channel with no messages whose only job is to hold others.
	"kind" VARCHAR(16) NOT NULL,
	-- Channel name, lowercased and hyphenated for text channels.
	"name" VARCHAR(100) NOT NULL,
	-- Header description. Null for voice channels and categories.
	"topic" VARCHAR(1024),
	-- Manual sort order among siblings, which is why reordering is a set of integer updates.
	"position_index" SMALLINT NOT NULL DEFAULT 0,
	-- Gates entry behind an age confirmation.
	"is_nsfw" BOOLEAN NOT NULL DEFAULT false,
	-- Slow mode. Zero means off; the value is seconds between messages per user.
	"rate_limit_seconds" SMALLINT NOT NULL DEFAULT 0,
	-- Voice bitrate in bits per second. Null for anything that is not a voice channel.
	"bitrate" INTEGER,
	-- Maximum concurrent voice participants. Null means unlimited.
	"user_limit" SMALLINT,
	-- Channel creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "channels" IS 'Every kind of channel in one table, nested through parent_id. Categories share the table because permission overwrites apply to them and are inherited by their children.';
COMMENT ON COLUMN "channels"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "channels"."guild_id" IS 'Owning server.';
COMMENT ON COLUMN "channels"."parent_id" IS 'Containing category. Null for a top-level channel; a self-reference is how one table holds both categories and the channels inside them.';
COMMENT ON COLUMN "channels"."kind" IS 'text | voice | category | announcement | forum. A category is a channel with no messages whose only job is to hold others.';
COMMENT ON COLUMN "channels"."name" IS 'Channel name, lowercased and hyphenated for text channels.';
COMMENT ON COLUMN "channels"."topic" IS 'Header description. Null for voice channels and categories.';
COMMENT ON COLUMN "channels"."position_index" IS 'Manual sort order among siblings, which is why reordering is a set of integer updates.';
COMMENT ON COLUMN "channels"."is_nsfw" IS 'Gates entry behind an age confirmation.';
COMMENT ON COLUMN "channels"."rate_limit_seconds" IS 'Slow mode. Zero means off; the value is seconds between messages per user.';
COMMENT ON COLUMN "channels"."bitrate" IS 'Voice bitrate in bits per second. Null for anything that is not a voice channel.';
COMMENT ON COLUMN "channels"."user_limit" IS 'Maximum concurrent voice participants. Null means unlimited.';
COMMENT ON COLUMN "channels"."created_at" IS 'Channel creation time.';

CREATE INDEX "idx_channels_guild_parent_position"
ON "channels" ("guild_id", "parent_id", "position_index");

CREATE TABLE IF NOT EXISTS "roles" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Server the role belongs to. Roles never cross servers.
	"guild_id" BIGINT NOT NULL,
	-- Role name shown in the member list.
	"name" VARCHAR(100) NOT NULL,
	-- Permission bitfield. One 64-bit integer instead of fifty boolean columns, so adding a permission is a new bit rather than a migration.
	"permissions" BIGINT NOT NULL DEFAULT 0,
	-- Packed 24-bit RGB. Zero means no colour, and the highest positioned coloured role wins on a member.
	"color_rgb" INTEGER NOT NULL DEFAULT 0,
	-- Role hierarchy. Higher positions outrank lower ones, which is what decides who may kick or edit whom.
	"position_index" SMALLINT NOT NULL DEFAULT 0,
	-- Shows holders in their own member-list section.
	"is_hoisted" BOOLEAN NOT NULL DEFAULT false,
	-- Whether anyone may ping the whole role.
	"is_mentionable" BOOLEAN NOT NULL DEFAULT false,
	-- True for a role created and owned by an integration; humans cannot edit or delete it.
	"is_managed" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "roles" IS 'A named bundle of permissions, scoped to one server. The bitfield is the server-wide baseline; per-channel overwrites adjust it without touching this row.';
COMMENT ON COLUMN "roles"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "roles"."guild_id" IS 'Server the role belongs to. Roles never cross servers.';
COMMENT ON COLUMN "roles"."name" IS 'Role name shown in the member list.';
COMMENT ON COLUMN "roles"."permissions" IS 'Permission bitfield. One 64-bit integer instead of fifty boolean columns, so adding a permission is a new bit rather than a migration.';
COMMENT ON COLUMN "roles"."color_rgb" IS 'Packed 24-bit RGB. Zero means no colour, and the highest positioned coloured role wins on a member.';
COMMENT ON COLUMN "roles"."position_index" IS 'Role hierarchy. Higher positions outrank lower ones, which is what decides who may kick or edit whom.';
COMMENT ON COLUMN "roles"."is_hoisted" IS 'Shows holders in their own member-list section.';
COMMENT ON COLUMN "roles"."is_mentionable" IS 'Whether anyone may ping the whole role.';
COMMENT ON COLUMN "roles"."is_managed" IS 'True for a role created and owned by an integration; humans cannot edit or delete it.';

CREATE INDEX "idx_roles_guild_position"
ON "roles" ("guild_id", "position_index");

CREATE TABLE IF NOT EXISTS "guild_members" (
	-- Surrogate primary key. A join table would use a composite key, but role assignments point at this row.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Server joined.
	"guild_id" BIGINT NOT NULL,
	-- Account that joined.
	"user_id" BIGINT NOT NULL,
	-- Per-server display name. Null falls back to the global display name, then the username. This column is the reason membership is its own table.
	"nickname" VARCHAR(32),
	-- Join time; drives the "member since" label and join-order sorting.
	"joined_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Timeout expiry. Null means not timed out, which is cheaper to check than a separate moderation table.
	"muted_until" TIMESTAMP,
	-- Server-wide voice deafen applied by a moderator.
	"is_deafened" BOOLEAN NOT NULL DEFAULT false,
	-- When this member started boosting the server. Null for non-boosters.
	"boost_since" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "guild_members" IS 'One row per account per server. Everything that is true of a person only inside one server lives here rather than on users.';
COMMENT ON COLUMN "guild_members"."id" IS 'Surrogate primary key. A join table would use a composite key, but role assignments point at this row.';
COMMENT ON COLUMN "guild_members"."guild_id" IS 'Server joined.';
COMMENT ON COLUMN "guild_members"."user_id" IS 'Account that joined.';
COMMENT ON COLUMN "guild_members"."nickname" IS 'Per-server display name. Null falls back to the global display name, then the username. This column is the reason membership is its own table.';
COMMENT ON COLUMN "guild_members"."joined_at" IS 'Join time; drives the "member since" label and join-order sorting.';
COMMENT ON COLUMN "guild_members"."muted_until" IS 'Timeout expiry. Null means not timed out, which is cheaper to check than a separate moderation table.';
COMMENT ON COLUMN "guild_members"."is_deafened" IS 'Server-wide voice deafen applied by a moderator.';
COMMENT ON COLUMN "guild_members"."boost_since" IS 'When this member started boosting the server. Null for non-boosters.';

CREATE UNIQUE INDEX "uq_guild_members_guild_user"
ON "guild_members" ("guild_id", "user_id");
CREATE INDEX "idx_guild_members_user"
ON "guild_members" ("user_id");

CREATE TABLE IF NOT EXISTS "member_roles" (
	-- Membership being granted the role, part of the composite key.
	"guild_member_id" BIGINT,
	-- Role granted, part of the composite key.
	"role_id" BIGINT,
	-- When the role was granted; useful for auditing a privilege escalation.
	"assigned_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("guild_member_id", "role_id")
);

COMMENT ON TABLE "member_roles" IS 'Many-to-many between memberships and roles, with a composite key and no surrogate id. A member effective server permissions are the bitwise OR of every role here plus the guild default.';
COMMENT ON COLUMN "member_roles"."guild_member_id" IS 'Membership being granted the role, part of the composite key.';
COMMENT ON COLUMN "member_roles"."role_id" IS 'Role granted, part of the composite key.';
COMMENT ON COLUMN "member_roles"."assigned_at" IS 'When the role was granted; useful for auditing a privilege escalation.';

CREATE INDEX "idx_member_roles_role"
ON "member_roles" ("role_id");

CREATE TABLE IF NOT EXISTS "channel_overwrites" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Channel or category the overwrite applies to.
	"channel_id" BIGINT NOT NULL,
	-- Role targeted. Exactly one of role_id and user_id is set; a check constraint enforces that.
	"role_id" BIGINT,
	-- Individual member targeted. Member overwrites are applied after role overwrites and therefore win.
	"user_id" BIGINT,
	-- Bits explicitly granted here, applied after the deny mask.
	"allow_bits" BIGINT NOT NULL DEFAULT 0,
	-- Bits explicitly revoked here. Kept separate from allow so "not mentioned" and "explicitly denied" are different states.
	"deny_bits" BIGINT NOT NULL DEFAULT 0,
	-- When the overwrite was set.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "channel_overwrites" IS 'The centrepiece. Three-state permissions per channel - inherit, allow, deny - expressed as two masks, resolved in order: guild default, roles, @everyone overwrite, role overwrites, then the member overwrite.';
COMMENT ON COLUMN "channel_overwrites"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "channel_overwrites"."channel_id" IS 'Channel or category the overwrite applies to.';
COMMENT ON COLUMN "channel_overwrites"."role_id" IS 'Role targeted. Exactly one of role_id and user_id is set; a check constraint enforces that.';
COMMENT ON COLUMN "channel_overwrites"."user_id" IS 'Individual member targeted. Member overwrites are applied after role overwrites and therefore win.';
COMMENT ON COLUMN "channel_overwrites"."allow_bits" IS 'Bits explicitly granted here, applied after the deny mask.';
COMMENT ON COLUMN "channel_overwrites"."deny_bits" IS 'Bits explicitly revoked here. Kept separate from allow so "not mentioned" and "explicitly denied" are different states.';
COMMENT ON COLUMN "channel_overwrites"."created_at" IS 'When the overwrite was set.';

CREATE UNIQUE INDEX "uq_overwrites_channel_role"
ON "channel_overwrites" ("channel_id", "role_id");
CREATE UNIQUE INDEX "uq_overwrites_channel_user"
ON "channel_overwrites" ("channel_id", "user_id");

CREATE TABLE IF NOT EXISTS "messages" (
	-- Surrogate primary key, monotonically increasing so it doubles as the pagination cursor.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Channel the message was posted in. A thread message keeps its parent channel here too, so channel-wide moderation still finds it.
	"channel_id" BIGINT NOT NULL,
	-- Thread the message belongs to. Null for a message in the channel proper.
	"thread_id" BIGINT,
	-- Who sent it. Bots and humans are both users, so there is one column.
	"author_id" BIGINT NOT NULL,
	-- Message body. Null for an attachment-only or embed-only message.
	"content" VARCHAR(4000),
	-- Message being replied to. Null for a normal message; set null if the target is hard-deleted.
	"reply_to_message_id" BIGINT,
	-- Denormalised flag, because notification fan-out must not parse the body on read.
	"mention_everyone" BOOLEAN NOT NULL DEFAULT false,
	-- Pinned to the channel. A flag rather than a table because the limit is small and fixed.
	"is_pinned" BOOLEAN NOT NULL DEFAULT false,
	-- Send time.
	"sent_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Last edit. Null means never edited, which is what renders the (edited) marker.
	"edited_at" TIMESTAMP,
	-- Soft delete, so replies and thread starters do not dangle.
	"deleted_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "messages" IS 'Every message in one table, with the thread id as an optional discriminator. Keeping channel_id populated for thread messages is what makes channel-level moderation and search a single index scan.';
COMMENT ON COLUMN "messages"."id" IS 'Surrogate primary key, monotonically increasing so it doubles as the pagination cursor.';
COMMENT ON COLUMN "messages"."channel_id" IS 'Channel the message was posted in. A thread message keeps its parent channel here too, so channel-wide moderation still finds it.';
COMMENT ON COLUMN "messages"."thread_id" IS 'Thread the message belongs to. Null for a message in the channel proper.';
COMMENT ON COLUMN "messages"."author_id" IS 'Who sent it. Bots and humans are both users, so there is one column.';
COMMENT ON COLUMN "messages"."content" IS 'Message body. Null for an attachment-only or embed-only message.';
COMMENT ON COLUMN "messages"."reply_to_message_id" IS 'Message being replied to. Null for a normal message; set null if the target is hard-deleted.';
COMMENT ON COLUMN "messages"."mention_everyone" IS 'Denormalised flag, because notification fan-out must not parse the body on read.';
COMMENT ON COLUMN "messages"."is_pinned" IS 'Pinned to the channel. A flag rather than a table because the limit is small and fixed.';
COMMENT ON COLUMN "messages"."sent_at" IS 'Send time.';
COMMENT ON COLUMN "messages"."edited_at" IS 'Last edit. Null means never edited, which is what renders the (edited) marker.';
COMMENT ON COLUMN "messages"."deleted_at" IS 'Soft delete, so replies and thread starters do not dangle.';

CREATE INDEX "idx_messages_channel_sent"
ON "messages" ("channel_id", "sent_at");
CREATE INDEX "idx_messages_thread_sent"
ON "messages" ("thread_id", "sent_at");
CREATE INDEX "idx_messages_author"
ON "messages" ("author_id");

CREATE TABLE IF NOT EXISTS "threads" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Channel the thread hangs off. A thread inherits that channel resolved permissions rather than carrying its own overwrites.
	"parent_channel_id" BIGINT NOT NULL,
	-- Message the thread was created from. Null for a standalone thread started from the composer.
	"starter_message_id" BIGINT,
	-- Who opened the thread. Null once that account is deleted.
	"creator_id" BIGINT,
	-- Thread title shown in the thread list.
	"name" VARCHAR(100) NOT NULL,
	-- Archived threads drop out of the sidebar but stay fully readable and searchable.
	"is_archived" BOOLEAN NOT NULL DEFAULT false,
	-- Idle minutes before auto-archiving. Stored per thread because the server default can change later.
	"auto_archive_minutes" INTEGER NOT NULL DEFAULT 1440,
	-- Denormalised count, maintained on write so the thread list does not aggregate on every render.
	"message_count" INTEGER NOT NULL DEFAULT 0,
	-- Thread creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Newest message time; drives the archive timer and the sidebar ordering.
	"last_message_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "threads" IS 'A sub-conversation inside a channel. Modelled as its own table rather than as a channel, because it has no overwrites, no position and no category - it borrows all of that from its parent.';
COMMENT ON COLUMN "threads"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "threads"."parent_channel_id" IS 'Channel the thread hangs off. A thread inherits that channel resolved permissions rather than carrying its own overwrites.';
COMMENT ON COLUMN "threads"."starter_message_id" IS 'Message the thread was created from. Null for a standalone thread started from the composer.';
COMMENT ON COLUMN "threads"."creator_id" IS 'Who opened the thread. Null once that account is deleted.';
COMMENT ON COLUMN "threads"."name" IS 'Thread title shown in the thread list.';
COMMENT ON COLUMN "threads"."is_archived" IS 'Archived threads drop out of the sidebar but stay fully readable and searchable.';
COMMENT ON COLUMN "threads"."auto_archive_minutes" IS 'Idle minutes before auto-archiving. Stored per thread because the server default can change later.';
COMMENT ON COLUMN "threads"."message_count" IS 'Denormalised count, maintained on write so the thread list does not aggregate on every render.';
COMMENT ON COLUMN "threads"."created_at" IS 'Thread creation time.';
COMMENT ON COLUMN "threads"."last_message_at" IS 'Newest message time; drives the archive timer and the sidebar ordering.';

CREATE INDEX "idx_threads_channel_active"
ON "threads" ("parent_channel_id", "is_archived", "last_message_at");

CREATE TABLE IF NOT EXISTS "message_reactions" (
	-- Message reacted to, part of the composite key.
	"message_id" BIGINT,
	-- Who reacted, part of the composite key.
	"user_id" BIGINT,
	-- Unicode emoji or custom emoji reference, part of the key. Three columns is exactly the uniqueness rule: one person, one emoji, one message.
	"emoji" VARCHAR(64),
	-- When the reaction was added; the hover list is ordered by it.
	"reacted_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("message_id", "user_id", "emoji")
);

COMMENT ON TABLE "message_reactions" IS 'A composite key that is also the business rule. Counts are aggregated from these rows rather than stored, because reaction removal is as common as addition.';
COMMENT ON COLUMN "message_reactions"."message_id" IS 'Message reacted to, part of the composite key.';
COMMENT ON COLUMN "message_reactions"."user_id" IS 'Who reacted, part of the composite key.';
COMMENT ON COLUMN "message_reactions"."emoji" IS 'Unicode emoji or custom emoji reference, part of the key. Three columns is exactly the uniqueness rule: one person, one emoji, one message.';
COMMENT ON COLUMN "message_reactions"."reacted_at" IS 'When the reaction was added; the hover list is ordered by it.';

CREATE INDEX "idx_reactions_message_emoji"
ON "message_reactions" ("message_id", "emoji");

CREATE TABLE IF NOT EXISTS "attachments" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Message the file is attached to. An attachment cannot exist on its own.
	"message_id" BIGINT NOT NULL,
	-- Object-store URL of the uploaded file.
	"file_url" VARCHAR(500) NOT NULL,
	-- Original filename as uploaded, shown in the UI and used on download.
	"filename" VARCHAR(255) NOT NULL,
	-- MIME type, which decides whether the client renders an inline preview.
	"content_type" VARCHAR(120) NOT NULL,
	-- File size, checked against the server boost tier upload limit.
	"size_bytes" BIGINT NOT NULL,
	-- Image or video width. Null for a non-visual file.
	"width_px" INTEGER,
	-- Image or video height. Null for a non-visual file.
	"height_px" INTEGER,
	-- Renders blurred until clicked.
	"is_spoiler" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "attachments" IS 'Files, one row each, because a single message can carry several. Metadata is stored rather than probed, so the client can lay out the grid before any byte downloads.';
COMMENT ON COLUMN "attachments"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "attachments"."message_id" IS 'Message the file is attached to. An attachment cannot exist on its own.';
COMMENT ON COLUMN "attachments"."file_url" IS 'Object-store URL of the uploaded file.';
COMMENT ON COLUMN "attachments"."filename" IS 'Original filename as uploaded, shown in the UI and used on download.';
COMMENT ON COLUMN "attachments"."content_type" IS 'MIME type, which decides whether the client renders an inline preview.';
COMMENT ON COLUMN "attachments"."size_bytes" IS 'File size, checked against the server boost tier upload limit.';
COMMENT ON COLUMN "attachments"."width_px" IS 'Image or video width. Null for a non-visual file.';
COMMENT ON COLUMN "attachments"."height_px" IS 'Image or video height. Null for a non-visual file.';
COMMENT ON COLUMN "attachments"."is_spoiler" IS 'Renders blurred until clicked.';

CREATE INDEX "idx_attachments_message"
ON "attachments" ("message_id");

CREATE TABLE IF NOT EXISTS "invites" (
	-- The invite code itself, and the primary key - the URL is the identity, so there is no surrogate id.
	"code" VARCHAR(16),
	-- Server being joined.
	"guild_id" BIGINT NOT NULL,
	-- Landing channel. Null means the server default landing channel is used.
	"channel_id" BIGINT,
	-- Who created the invite. Null once that account is deleted, so the invite keeps working.
	"inviter_id" BIGINT,
	-- Zero means unlimited; any other value is the hard cap.
	"max_uses" INTEGER NOT NULL DEFAULT 0,
	-- Redemptions so far, incremented atomically so a burst cannot exceed max_uses.
	"use_count" INTEGER NOT NULL DEFAULT 0,
	-- Joiners are kicked on disconnect unless they are given a role first.
	"is_temporary" BOOLEAN NOT NULL DEFAULT false,
	-- Creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Expiry. Null means the invite never expires.
	"expires_at" TIMESTAMP,
	PRIMARY KEY("code")
);

COMMENT ON TABLE "invites" IS 'Keyed by the code because that is what a user pastes. Both limits are enforced here - a cap on uses and a wall-clock expiry - and either alone is insufficient.';
COMMENT ON COLUMN "invites"."code" IS 'The invite code itself, and the primary key - the URL is the identity, so there is no surrogate id.';
COMMENT ON COLUMN "invites"."guild_id" IS 'Server being joined.';
COMMENT ON COLUMN "invites"."channel_id" IS 'Landing channel. Null means the server default landing channel is used.';
COMMENT ON COLUMN "invites"."inviter_id" IS 'Who created the invite. Null once that account is deleted, so the invite keeps working.';
COMMENT ON COLUMN "invites"."max_uses" IS 'Zero means unlimited; any other value is the hard cap.';
COMMENT ON COLUMN "invites"."use_count" IS 'Redemptions so far, incremented atomically so a burst cannot exceed max_uses.';
COMMENT ON COLUMN "invites"."is_temporary" IS 'Joiners are kicked on disconnect unless they are given a role first.';
COMMENT ON COLUMN "invites"."created_at" IS 'Creation time.';
COMMENT ON COLUMN "invites"."expires_at" IS 'Expiry. Null means the invite never expires.';

CREATE INDEX "idx_invites_guild_expiry"
ON "invites" ("guild_id", "expires_at");

CREATE TABLE IF NOT EXISTS "voice_sessions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Voice channel joined.
	"channel_id" BIGINT NOT NULL,
	-- Participant.
	"user_id" BIGINT NOT NULL,
	-- Join instant. Start and end as separate columns make the session an interval you can overlap and sum.
	"joined_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Leave instant. Null means still connected, which is how the live participant list is read.
	"left_at" TIMESTAMP,
	-- Muted by the user themselves, distinct from a moderator mute on the membership row.
	"self_muted" BOOLEAN NOT NULL DEFAULT false,
	-- Screen share active at the last state update.
	"is_streaming" BOOLEAN NOT NULL DEFAULT false,
	-- Voice region the session was assigned to; kept for diagnosing quality complaints.
	"region" VARCHAR(40),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "voice_sessions" IS 'One row per connection, closed by left_at rather than deleted. Keeping the interval is what makes voice minutes, concurrency peaks and reconnect storms measurable after the fact.';
COMMENT ON COLUMN "voice_sessions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "voice_sessions"."channel_id" IS 'Voice channel joined.';
COMMENT ON COLUMN "voice_sessions"."user_id" IS 'Participant.';
COMMENT ON COLUMN "voice_sessions"."joined_at" IS 'Join instant. Start and end as separate columns make the session an interval you can overlap and sum.';
COMMENT ON COLUMN "voice_sessions"."left_at" IS 'Leave instant. Null means still connected, which is how the live participant list is read.';
COMMENT ON COLUMN "voice_sessions"."self_muted" IS 'Muted by the user themselves, distinct from a moderator mute on the membership row.';
COMMENT ON COLUMN "voice_sessions"."is_streaming" IS 'Screen share active at the last state update.';
COMMENT ON COLUMN "voice_sessions"."region" IS 'Voice region the session was assigned to; kept for diagnosing quality complaints.';

CREATE INDEX "idx_voice_sessions_channel_live"
ON "voice_sessions" ("channel_id", "left_at");
CREATE INDEX "idx_voice_sessions_user_joined"
ON "voice_sessions" ("user_id", "joined_at");

